SET plan_cache_mode=force_custom_plan; SET statement_timeout=120000; PREPARE hfs1579 AS SELECT id, version_id, data, last_updated, fhir_version, last_updated AS sort_key FROM resources WHERE tenant_id = $1 AND resource_type = $2 AND is_deleted = FALSE AND (((id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'patient' AND ((value_reference IS NOT NULL AND split_part(value_reference, '/', -1) = $3)))) AND (id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'code' AND (value_token_code = $4)))) AND (id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'value-quantity' AND ((value_quantity_value > $5 AND value_quantity_unit = $6) OR (value_quantity_canonical_value > $7 AND value_quantity_canonical_unit = $8))))) ORDER BY last_updated DESC, id ASC LIMIT 21;
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) EXECUTE hfs1579('default','Observation','7d24f7a0-6f2e-ce3b-5568-db7b14695583','8302-2',100.0,'cm',1.0,'m');
